export function estimateReadingMinutes(words: number, wordsPerMinute = 200) { return words ? Math.max(1, Math.ceil(words / wordsPerMinute)) : 0; }
export function estimateSpeakingMinutes(words: number, wordsPerMinute = 130) { return words ? Math.max(1, Math.ceil(words / wordsPerMinute)) : 0; }
export function formatMinutes(minutes: number) { return minutes === 0 ? "0 min" : `${minutes} min`; }
