export function estimatePromptApiCost(tokens: number, model: TokenModel) { return (tokens / 1_000_000) * MODEL_PLANNING_RATES_PER_MILLION[model]; }
export function formatEstimatedCost(cost: number) { return cost < 0.0001 ? "$0.0000" : `$${cost.toFixed(4)}`; }
export function isSupportedPromptFile(file: Pick<File, "name" | "type">) { return /\.(txt|md)$/i.test(file.name) || file.type === "text/plain" || file.type === "text/markdown"; }
