export function highlightCode(source: string, language: string) { const escaped = encode(source); const keywords = language.toLowerCase().includes("js") || language.toLowerCase().includes("ts") ? "const|let|var|function|return|if|else|import|from|export|async|await" : language.toLowerCase().includes("py") ? "def|return|if|else|import|from|for|in|class|True|False|None" : "true|false|null|undefined"; return escaped.replace(new RegExp(`\\b(${keywords})\\b`, "g"), '<span class="code-keyword">$1</span>').replace(/(&quot;.*?&quot;|&#39;.*?&#39;)/g, '<span class="code-string">$1</span>'); }
export function readLocalDraft(key: string, fallback: string) { try { return window.localStorage.getItem(key) ?? fallback; } catch { return fallback; } }
export function writeLocalDraft(key: string, value: string) { try { window.localStorage.setItem(key, value); } catch { /* Private browsing or blocked storage should not break the tool. */ } }
export function clearLocalDraft(key: string) { try { window.localStorage.removeItem(key); } catch { /* Ignore unavailable storage. */ } }
export type PromptHistoryEntry = { text: string; words: number; characters: number; lines: number; model: string; tokens: number; savedAt: number };
export function readPromptHistory(key: string): PromptHistoryEntry[] { try { const parsed: unknown = JSON.parse(window.localStorage.getItem(key) || "[]"); return Array.isArray(parsed) ? parsed.filter((item): item is PromptHistoryEntry => Boolean(item && typeof item === "object" && typeof (item as PromptHistoryEntry).text === "string" && typeof (item as PromptHistoryEntry).savedAt === "number")).slice(0, 5) : []; } catch { return []; } }
export function savePromptHistory(key: string, entry: PromptHistoryEntry) { try { const next = [entry, ...readPromptHistory(key).filter(item => item.text !== entry.text)].slice(0, 5); window.localStorage.setItem(key, JSON.stringify(next)); return next; } catch { return []; } }
export function clearPromptHistory(key: string) { clearLocalDraft(key); return []; }
