export function serializePromptHistory(entries: PromptHistoryEntry[]) { return JSON.stringify({ version: 1, tool: "ai-prompt-word-counter", entries: entries.slice(0, 5) }, null, 2); }
export function mergePromptHistory(existing: PromptHistoryEntry[], incoming: PromptHistoryEntry[]) { const byText = new Map<string, PromptHistoryEntry>(); [...existing, ...incoming].forEach(entry => { const current = byText.get(entry.text); if (!current || entry.savedAt >= current.savedAt) byText.set(entry.text, entry); }); return Array.from(byText.values()).sort((a, b) => b.savedAt - a.savedAt).slice(0, 5); }
